'use strict';

// MAIN //

/**
* Scans the file to extract all depth-0 `static` helpers (variables, functions, arrays).
*
* @private
* @param {Array<string>} lines - source lines
* @returns {Array<Object>} array of line objects for the static helpers
*
* @example
* var lines = [
*     'static void foo() {',
*     '    return;',
*     '}'
* ];
* var out = extractStaticHelpers( lines );
* // returns [ { 'text': 'static void foo() {', 'line': 1 }, ... ]
*/
function extractStaticHelpers( lines ) {
	var braceDepth;
	var inStatic;
	var clean;
	var line;
	var out;
	var i;

	out = [];
	inStatic = false;
	braceDepth = 0;

	for ( i = 0; i < lines.length; i++ ) {
		line = lines[ i ];

		if ( !inStatic && /^static\b/.test( line ) ) {
			inStatic = true;
			braceDepth = 0;
		}
		if ( inStatic ) {
			out.push({
				'text': line,
				'line': i + 1
			});

			braceDepth += ( line.match( /\{/g ) || [] ).length;
			braceDepth -= ( line.match( /\}/g ) || [] ).length;
			if ( braceDepth === 0 && ( /;/.test( clean ) || /\}/.test( clean ) ) ) {
				inStatic = false;
			}
		}
	}
	return out;
}


// EXPORTS //

module.exports = extractStaticHelpers;
